function pgStr(v) { return v === null || v === undefined || v === '' ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }

// Welle 1, AP1 (2026-07-31): $json ist hier der Rueckgabewert von "DB: Signal
// aktualisieren"/"neu anlegen" (Data-Table-Node, gibt nur die EIGENEN Spalten
// zurueck) - open/high/low/volume/adjusted_close/data_quality_status
// existieren dort nicht (gleiche Data-Table-Roundtrip-Falle wie bei ATR/
// Strategiesignalen). Direkt aus "Signal: flach aufbereiten" nachladen
// (.all()+Ticker-Matching, kein .item), exchange aus "Watchlist laden (Kurse)".
function sourceFor(ticker) {
  try {
    const all = $('Signal: flach aufbereiten').all();
    const match = all.find(i => i.json && i.json.ticker === ticker);
    return match ? match.json : {};
  } catch (e) { return {}; }
}
function exchangeFor(ticker) {
  try {
    const all = $('Watchlist laden (Kurse)').all();
    const match = all.find(i => i.json && i.json.ticker === ticker);
    return match && match.json ? match.json.exchange : null;
  } catch (e) { return null; }
}

const outer = $json;
const j = sourceFor(outer.ticker);
const exchange = exchangeFor(outer.ticker);

// Ohne verwertbaren Close kein sinnvoller Kurs-Datensatz - kein Schreiben
// statt einer kaputten Zeile (Auftragsvorgabe: kein technischer Fehler als
// neutrales/stilles Signal, aber auch kein erfundener Ersatzwert).
if (j.kerze_close === undefined || j.kerze_close === null || j.kerze_close === '' || isNaN(Number(j.kerze_close))) {
  return { json: { ...outer, sql: 'SELECT 1;' } };
}

const tradingDate = j.datum;
const sourceTs = j.kerze_timestamp ? new Date(Number(j.kerze_timestamp) * 1000).toISOString() : null;
const qualityStatus = j.data_quality_status || 'limited';

// Point-in-Time-Revisionierung wie fundamentals_history (sql/022/025): aktuelle
// Revision schliessen, neue Revision anlegen - kein ON CONFLICT DO UPDATE mehr,
// das bisher jeden Vortageswert kommentarlos ueberschrieben hat.
const sql = `UPDATE trading.stock_price_history
  SET valid_to = now()
  WHERE symbol = ${pgStr(j.ticker)} AND trading_date = ${pgStr(tradingDate)} AND valid_to IS NULL;

INSERT INTO trading.stock_price_history
  (symbol, trading_date, open, high, low, close, adjusted_close, volume, currency, exchange, source, source_timestamp, data_quality_status, revision_number)
  SELECT ${pgStr(j.ticker)}, ${pgStr(tradingDate)}, ${pgNum(j.kerze_open)}, ${pgNum(j.kerze_high)}, ${pgNum(j.kerze_low)}, ${pgNum(j.kerze_close)}, ${pgNum(j.kerze_adjusted_close)}, ${pgNum(j.kerze_volume)}, ${pgStr(j.waehrung)}, ${pgStr(exchange)}, 'technische-signale-02', ${pgStr(sourceTs)}, ${pgStr(qualityStatus)},
    COALESCE((SELECT MAX(revision_number) FROM trading.stock_price_history WHERE symbol = ${pgStr(j.ticker)} AND trading_date = ${pgStr(tradingDate)}), 0) + 1;`;

return { json: { ...outer, sql } };

const items = $input.all().map(i => i.json).filter(i => i.ticker !== undefined);
const total = items.length;
const errorItems = items.filter(i => i.status === 'fehler' || i.fehler);
const successful = total - errorItems.length;
const failed = errorItems.length;

let status;
if (total === 0) status = 'skipped';
else if (failed === 0) status = 'success';
else if (successful === 0) status = 'failed';
else status = 'partial_failure';

let startedAt = null;
try { startedAt = $('Watchlist laden (Kurse)').all()[0].json._run_started_at; } catch (e) {}
let runId = null;
try { runId = $('Execute Workflow Trigger').all()[0].json.context.run_id; } catch (e) {}

return [{ json: {
  ok: failed === 0,
  workflow: '02 \u2013 Technische Signale t\u00e4glich',
  run_id: runId,
  processed: total,
  successful,
  failed,
  warnings: [],
  errors: errorItems.map(i => ({ ticker: i.ticker, node: 'Kurs abrufen (lokaler FastAPI)', message: i.fehler || 'Unbekannter Fehler' })),
  started_at: startedAt,
  finished_at: new Date().toISOString(),
  status
} }];

function pgStr(v) { return v === null || v === undefined || v === '' ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgJsonb(v) { return (v === null || v === undefined) ? "'[]'::jsonb" : `'` + JSON.stringify(v).replace(/'/g, `''`) + `'::jsonb`; }

// Welle 2, AP1: normalisierte, historisierte Strategiesignale in
// trading.strategy_signals (sql/031). $json ist hier der Rueckgabewert von
// "DB: Signal aktualisieren"/"neu anlegen" (Data-Table-Node, nur eigene
// Spalten) - die vollstaendigen Signal-Objekte (inkl. der in Welle 2 neu
// ergaenzten stop/target/entry_zone/time_stop_at-Felder) muessen aus
// "Signal: flach aufbereiten" nachgeladen werden (.all()+Ticker-Matching,
// gleiches Muster wie ATR/Datenqualitaet in Welle 1).
function sourceFor(ticker) {
  try {
    const all = $('Signal: flach aufbereiten').all();
    const match = all.find(i => i.json && i.json.ticker === ticker);
    return match ? match.json : {};
  } catch (e) { return {}; }
}
const outer = $json;
const j = sourceFor(outer.ticker);
const businessDate = j.datum;

function parseSignal(fieldName) {
  try { return j[fieldName] ? JSON.parse(j[fieldName]) : null; } catch (e) { return null; }
}
const signals = [
  parseSignal('mean_reversion_signal_json'),
  parseSignal('trend_following_signal_json'),
  parseSignal('breakout_signal_json')
].filter(s => s !== null);

if (signals.length === 0 || !j.ticker || !businessDate) {
  return { json: { ...outer, sql: 'SELECT 1;' } };
}

const statements = [];
for (const s of signals) {
  statements.push(`UPDATE trading.strategy_signals
    SET valid_to = now()
    WHERE ticker = ${pgStr(j.ticker)} AND business_date = ${pgStr(businessDate)} AND strategy = ${pgStr(s.strategy)} AND valid_to IS NULL;`);
  statements.push(`INSERT INTO trading.strategy_signals
    (ticker, business_date, strategy, direction, raw_score, regime_fit, data_quality_score,
     entry_zone_low, entry_zone_high, stop_price, target_price, expected_horizon_days,
     time_stop_at, evidence_json, blockers_json, rule_version, revision_number)
    SELECT ${pgStr(j.ticker)}, ${pgStr(businessDate)}, ${pgStr(s.strategy)}, ${pgStr(s.direction)},
      ${pgNum(s.raw_score)}, ${pgNum(s.regime_fit)}, ${pgNum(s.data_quality)},
      ${pgNum(s.entry_zone_low)}, ${pgNum(s.entry_zone_high)}, ${pgNum(s.stop_price)}, ${pgNum(s.target_price)},
      ${pgNum(s.expected_horizon_days)}, ${pgStr(s.time_stop_at)}, ${pgJsonb(s.evidence || [])}, ${pgJsonb(s.blockers || [])},
      ${pgStr(s.rule_version || 'strategy-v1')},
      COALESCE((SELECT MAX(revision_number) FROM trading.strategy_signals WHERE ticker = ${pgStr(j.ticker)} AND business_date = ${pgStr(businessDate)} AND strategy = ${pgStr(s.strategy)}), 0) + 1;`);
}

return { json: { ...outer, sql: statements.join('\n') } };

// TECHNISCHE ANALYSE – Yahoo/Finnhub/Stooq-Chartformat
// Modus im n8n Code Node: runOnceForEachItem
// Erweitert:
// - echte MACD-Signal-Linie
// - echte MACD-Kreuzung
// - praktische Handelsbewertung mit Gebührenpuffer, Ziel, Risiko, CRV
// - Status: handelskandidat / beobachten / nur_info / ignorieren

const input = $input.item.json;
// Robust: FastAPI-Antwort kann direkt in json oder unter json.body liegen
const inputData = (input.chart) ? input : (input.body || input);

// Watchlist-Daten aus vorherigem Node holen.
// Falls dein Kurs-Service ticker/name direkt mitgibt, werden diese bevorzugt.
let ticker = input.ticker || '';
let name = input.name || ticker;
let sektor = input.sektor || '';

try {
  const wl = $('Watchlist laden (Kurse)').item.json;
  ticker = input.ticker || wl.ticker || ticker;
  name = input.name || wl.name || name;
  sektor = input.sektor || wl.sektor || sektor;
} catch (e) {
  // Falls der Watchlist-Node nicht gefunden wird, bleiben input.ticker/input.name/input.sektor aktiv.
}

try {
  if (!inputData.chart || !inputData.chart.result || !inputData.chart.result[0]) {
    return {
      json: {
        type: 'technical_signal',
        ticker,
        name,
        sektor,
        fehler: 'Keine Chartdaten vorhanden',
        zeitstempel: new Date().toISOString()
      }
    };
  }

  const chart = inputData.chart.result[0];
  const meta = chart.meta || {};
  const quote = chart.indicators?.quote?.[0];

  if (!quote) {
    return {
      json: {
        type: 'technical_signal',
        ticker,
        name,
        sektor,
        fehler: 'Keine Quote-Daten vorhanden',
        zeitstempel: new Date().toISOString()
      }
    };
  }

  // ------------------------------------------------------------
  // Welle 1, AP1+AP2+AP3 (2026-07-31): Kerzenbildung pro Zeitstempel statt vier
  // unabhaengig gefilterter Arrays. Ausgangsbefund: quote.close/.high/.low/
  // .volume wurden bisher UNABHAENGIG voneinander gefiltert - fehlt an Tag X
  // nur "high", verschieben sich ab dort alle Folge-Tage in high[] gegenueber
  // close[] um eine Position (reales Risiko, auch wenn AAPL/SAP.DE am
  // 2026-07-31 live geprueft sauber waren, siehe docs/DATENQUALITAET_UND_SESSIONS.md).
  // Jede Kerze wird jetzt ueber ihren gemeinsamen Zeitstempel gebildet; nur
  // vollstaendig konsistente Kerzen fliessen in closes/highs/lows (und damit
  // in ATR/RSI/MACD/BB/52w/Breakout) ein.
  const rawTimestamps = chart.timestamp || [];
  const rawOpen = quote.open || [];
  const rawHigh = quote.high || [];
  const rawLow = quote.low || [];
  const rawClose = quote.close || [];
  const rawVolume = quote.volume || [];
  const adjCloseArr = (chart.indicators && chart.indicators.adjclose && chart.indicators.adjclose[0] && chart.indicators.adjclose[0].adjclose) || [];

  const qualityIssues = [];
  const rawLens = [rawTimestamps.length, rawOpen.length, rawHigh.length, rawLow.length, rawClose.length];
  if (new Set(rawLens).size > 1) qualityIssues.push('abweichende_arraylaenge');
  const n0 = rawTimestamps.length;

  const rohKerzen = [];
  for (let i = 0; i < n0; i++) {
    rohKerzen.push({
      ts: rawTimestamps[i],
      open: rawOpen[i] != null ? Number(rawOpen[i]) : null,
      high: rawHigh[i] != null ? Number(rawHigh[i]) : null,
      low: rawLow[i] != null ? Number(rawLow[i]) : null,
      close: rawClose[i] != null ? Number(rawClose[i]) : null,
      volume: rawVolume[i] != null ? Number(rawVolume[i]) : null,
      adjClose: adjCloseArr[i] != null ? Number(adjCloseArr[i]) : null
    });
  }

  // Duplikate/unsortierte Zeitstempel erkennen, dann defensiv bereinigen
  // (letzter Wert je Zeitstempel gewinnt, aufsteigend sortiert).
  const seenTs = new Set();
  let duplicateCount = 0, unsortedCount = 0;
  for (let i = 0; i < rohKerzen.length; i++) {
    if (seenTs.has(rohKerzen[i].ts)) duplicateCount++;
    seenTs.add(rohKerzen[i].ts);
    if (i > 0 && rohKerzen[i].ts < rohKerzen[i - 1].ts) unsortedCount++;
  }
  if (duplicateCount > 0) qualityIssues.push('doppelte_zeitstempel');
  if (unsortedCount > 0) qualityIssues.push('unsortierte_zeitstempel');
  const byTs = new Map();
  for (const k of rohKerzen) if (k.ts != null) byTs.set(k.ts, k);
  const kerzenSortiert = Array.from(byTs.values()).sort((a, b) => a.ts - b.ts);

  // Zeilen-Pruefung je Kerze (AP2): nur vollstaendig konsistente Kerzen duerfen
  // in die fuer ATR/RSI/MACD/BB/52w genutzten Arrays einfliessen.
  function kerzePruefen(k) {
    const issues = [];
    if (k.close == null || isNaN(k.close)) issues.push('close_fehlt');
    if (k.high == null || k.low == null) issues.push('high_oder_low_fehlt');
    if (k.high != null && k.low != null && k.high < k.low) issues.push('high_kleiner_low');
    if (k.open != null && k.high != null && k.low != null && (k.open > k.high || k.open < k.low)) issues.push('open_ausserhalb_high_low');
    if (k.close != null && k.high != null && k.low != null && (k.close > k.high || k.close < k.low)) issues.push('close_ausserhalb_high_low');
    if (k.volume != null && k.volume < 0) issues.push('negatives_volumen');
    return issues;
  }

  const gueltigeKerzen = [];
  let ungueltigeZeilen = 0;
  for (const k of kerzenSortiert) {
    const issues = kerzePruefen(k);
    k.rowIssues = issues;
    k.rowValid = issues.length === 0;
    if (k.rowValid) gueltigeKerzen.push(k); else ungueltigeZeilen++;
  }
  if (ungueltigeZeilen > 0) qualityIssues.push('ungueltige_kerzen_verworfen(' + ungueltigeZeilen + ')');

  // Grobe Split-/Datenanomalie-Heuristik: Tagesbewegung >40% ist bei diesen
  // Bluechip-Werten eher ein Datenfehler als eine reale Bewegung - wird NICHT
  // automatisch verworfen (koennte real sein), nur vermerkt.
  let splitVerdacht = 0;
  for (let i = 1; i < gueltigeKerzen.length; i++) {
    const prev = gueltigeKerzen[i - 1].close, cur = gueltigeKerzen[i].close;
    if (prev > 0 && Math.abs((cur - prev) / prev) > 0.4) splitVerdacht++;
  }
  if (splitVerdacht > 0) qualityIssues.push('moegliche_split_oder_datenanomalie(' + splitVerdacht + ')');

  // Session-Frische: liegt die juengste gueltige Kerze zu weit in der
  // Vergangenheit (Feed liefert offenbar keine aktuellen Daten mehr)?
  const letzteGueltigeKerze = gueltigeKerzen[gueltigeKerzen.length - 1];
  const alterTage = letzteGueltigeKerze ? (Date.now() / 1000 - letzteGueltigeKerze.ts) / 86400 : null;
  const zuAlt = alterTage !== null && alterTage > 5;
  if (zuAlt) qualityIssues.push('letzte_kerze_aelter_als_5_tage');

  const closes = gueltigeKerzen.map(k => k.close);
  const highs = gueltigeKerzen.map(k => k.high);
  const lows = gueltigeKerzen.map(k => k.low);
  const vols = rawVolume.filter(v => v != null && !isNaN(v) && v > 0);

  // AP3: echte Mindest-Zeitraeume je Verwendungszweck. closes.length ist nach
  // der Zeilen-Pruefung oben die Anzahl WIRKLICH nutzbarer Handelstage.
  const kurzfristHistoryAusreichend = closes.length >= 20;
  const volatilityHistoryAusreichend = closes.length >= 60;
  // 52-Wochen-Breakout: nur "ausreichend", wenn entweder das Meta-Feld
  // fiftyTwoWeekHigh/-Low vorliegt (ein echter, von der Quelle selbst
  // gepflegter 52-Wochen-Wert, unabhaengig vom Abrufzeitraum) ODER
  // mindestens 252 gueltige Handelstage tatsaechlich vorliegen. Ohne beides
  // darf keine Naehe zu einem "52-Wochen"-Hoch/-Tief behauptet werden.
  const hatMeta52w = meta.fiftyTwoWeekHigh != null && meta.fiftyTwoWeekHigh !== '';
  const breakoutHistoryAusreichend = hatMeta52w || closes.length >= 252;
  if (!breakoutHistoryAusreichend) qualityIssues.push('unter_252_handelstage_kein_meta_52w');

  if (closes.length < 35) {
    return {
      json: {
        type: 'technical_signal',
        ticker,
        name,
        sektor,
        fehler: 'Zu wenige Datenpunkte (' + closes.length + ')',
        dataQualityIssues: qualityIssues,
        zeitstempel: new Date().toISOString()
      }
    };
  }

  // Serien-Ebene Datenqualitaet (AP2): ein hoher Score darf den Status NICHT
  // ueberstimmen - 06 muss zuerst den Status pruefen, dann erst den Score.
  let dataQualityStatus = 'valid';
  if (zuAlt) {
    dataQualityStatus = 'stale';
  } else if (qualityIssues.includes('abweichende_arraylaenge') || ungueltigeZeilen > closes.length * 0.2 || !kurzfristHistoryAusreichend) {
    dataQualityStatus = 'invalid';
  } else if (!breakoutHistoryAusreichend || !volatilityHistoryAusreichend || ungueltigeZeilen > 0 || duplicateCount > 0 || unsortedCount > 0) {
    dataQualityStatus = 'limited';
  }
  const dataQualityScore = round(Math.max(0, Math.min(100,
    100
    - (ungueltigeZeilen > 0 ? Math.min(30, ungueltigeZeilen * 3) : 0)
    - (breakoutHistoryAusreichend ? 0 : 15)
    - (volatilityHistoryAusreichend ? 0 : 10)
    - (duplicateCount > 0 ? 10 : 0)
    - (unsortedCount > 0 ? 10 : 0)
    - (zuAlt ? 40 : 0)
    - (splitVerdacht > 0 ? 5 : 0)
  )), 1);

  // AP4: Sitzungsstatus aus der zentralen View (sql/027), von einem separaten
  // Postgres-Node einmal je Lauf geladen (siehe "DB: Sitzungsstatus laden").
  let sessionStatus = 'unknown';
  try {
    const sessionRows = $('DB: Sitzungsstatus laden').all().map(r => r.json);
    const sr = sessionRows.find(r => String(r.ticker || '').trim() === ticker);
    if (sr && sr.session_status) sessionStatus = sr.session_status;
  } catch (e) {
    // Node nicht gefunden/nicht ausgefuehrt - bleibt beim sicheren Default 'unknown'.
  }
  if (sessionStatus === 'open_intraday') {
    dataQualityStatus = 'session_incomplete';
    qualityIssues.push('sitzung_laeuft_noch');
  }
  // ------------------------------------------------------------
  // Phase 7 (fachliche Ueberarbeitung, Paket 16, 2026-07-31): ATR, realisierte
  // Volatilitaet, durchschnittliche Tagesrange. Rechnet direkt auf den bereits
  // oben extrahierten highs/lows/closes-Arrays (FastAPI liefert 35+ Handelstage
  // je Abruf) statt auf trading.stock_price_history zu warten, das aktuell nur
  // 'close' speichert und kaum Tiefe hat. ATR/Volatilitaet bleiben NULL bei
  // unzureichender Historie statt einen Wert zu erfinden (Auftragsvorgabe).
  // Multiplikatoren zentral hier definiert (einzige Stelle, die ATR-Stop/-Ziel
  // berechnet), nicht verteilt auf mehrere Nodes.
  // ------------------------------------------------------------
  const ATR_PERIOD = 14;
  const ATR_STOP_MULTIPLIER = 1.5;
  const ATR_TARGET_MULTIPLIER = 2.5;

  function computeATR(h, l, c, period) {
    if (h.length <= period || l.length <= period || c.length <= period) return null;
    const n = Math.min(h.length, l.length, c.length);
    const trueRanges = [];
    for (let i = 1; i < n; i++) {
      const tr = Math.max(h[i] - l[i], Math.abs(h[i] - c[i - 1]), Math.abs(l[i] - c[i - 1]));
      trueRanges.push(tr);
    }
    if (trueRanges.length < period) return null;
    let atr = trueRanges.slice(0, period).reduce((a, b) => a + b, 0) / period;
    for (let i = period; i < trueRanges.length; i++) {
      atr = (atr * (period - 1) + trueRanges[i]) / period;
    }
    return atr;
  }

  function computeRealizedVol(c, days) {
    if (c.length <= days) return null;
    const recent = c.slice(-(days + 1));
    const returns = [];
    for (let i = 1; i < recent.length; i++) {
      if (recent[i - 1] > 0) returns.push(Math.log(recent[i] / recent[i - 1]));
    }
    if (returns.length < days) return null;
    const mean = returns.reduce((a, b) => a + b, 0) / returns.length;
    const variance = returns.reduce((a, b) => a + (b - mean) * (b - mean), 0) / (returns.length - 1);
    return Math.sqrt(variance) * Math.sqrt(252);
  }

  function computeAvgDailyRange(h, l, period) {
    const n = Math.min(h.length, l.length);
    if (n < period) return null;
    const recentH = h.slice(-period);
    const recentL = l.slice(-period);
    let sum = 0;
    for (let i = 0; i < period; i++) sum += (recentH[i] - recentL[i]);
    return sum / period;
  }

  const atr14 = computeATR(highs, lows, closes, ATR_PERIOD);
  const realizedVol20 = computeRealizedVol(closes, 20);
  const realizedVol60 = computeRealizedVol(closes, 60);
  const avgDailyRange14 = computeAvgDailyRange(highs, lows, ATR_PERIOD);


  const aktuellerKurs = closes[closes.length - 1];
  const vorherigerKurs = closes[closes.length - 2];

  const veraenderungPctRaw = ((aktuellerKurs - vorherigerKurs) / vorherigerKurs) * 100;
  const veraenderung = veraenderungPctRaw.toFixed(2) + '%';
  const veraenderungPct = Math.abs(veraenderungPctRaw);

  // ------------------------------------------------------------
  // Hilfsfunktionen
  // ------------------------------------------------------------

  function ema(arr, p) {
    if (!arr || arr.length < p) return null;

    const k = 2 / (p + 1);
    let e = arr.slice(0, p).reduce((a, b) => a + b, 0) / p;

    for (let i = p; i < arr.length; i++) {
      e = arr[i] * k + e * (1 - k);
    }

    return e;
  }

  function emaSeries(arr, p) {
    if (!arr || arr.length < p) return [];

    const k = 2 / (p + 1);
    const result = [];

    let e = arr.slice(0, p).reduce((a, b) => a + b, 0) / p;

    for (let i = 0; i < arr.length; i++) {
      if (i < p - 1) {
        result.push(null);
      } else if (i === p - 1) {
        result.push(e);
      } else {
        e = arr[i] * k + e * (1 - k);
        result.push(e);
      }
    }

    return result;
  }

  function rsi(arr, p = 14) {
    if (!arr || arr.length <= p) return null;

    let gains = 0;
    let losses = 0;

    for (let i = arr.length - p; i < arr.length; i++) {
      const diff = arr[i] - arr[i - 1];
      if (diff > 0) {
        gains += diff;
      } else {
        losses += Math.abs(diff);
      }
    }

    const avgGain = gains / p;
    const avgLoss = losses / p;

    if (avgLoss === 0) return 100;

    return 100 - (100 / (1 + avgGain / avgLoss));
  }

  function round(value, digits = 2) {
    if (value == null || isNaN(value)) return null;
    return parseFloat(value.toFixed(digits));
  }

  function pctMove(from, to) {
    if (!from || !to || from <= 0 || to <= 0) return null;
    return ((to - from) / from) * 100;
  }

  function absPctMove(from, to) {
    const p = pctMove(from, to);
    return p === null ? null : Math.abs(p);
  }

  // ------------------------------------------------------------
  // RSI
  // ------------------------------------------------------------

  const rsiRaw = rsi(closes, 14);
  const rsiVal = round(rsiRaw, 1);

  if (rsiVal === null) {
    return {
      json: {
        type: 'technical_signal',
        ticker,
        name,
        sektor,
        fehler: 'RSI konnte nicht berechnet werden',
        zeitstempel: new Date().toISOString()
      }
    };
  }

  let rsiSignal = 'Neutral';

  if (rsiVal < 25) {
    rsiSignal = 'STARK ÜBERVERKAUFT (Long-Chance)';
  } else if (rsiVal < 35) {
    rsiSignal = 'Überverkauft';
  } else if (rsiVal > 75) {
    rsiSignal = 'STARK ÜBERKAUFT (Short-Chance)';
  } else if (rsiVal > 65) {
    rsiSignal = 'Überkauft';
  }

  // ------------------------------------------------------------
  // Echter MACD: MACD-Linie, Signal-Linie, Histogramm
  // ------------------------------------------------------------

  const ema12Series = emaSeries(closes, 12);
  const ema26Series = emaSeries(closes, 26);

  const macdFullSeries = closes.map((_, i) => {
    if (ema12Series[i] == null || ema26Series[i] == null) return null;
    return ema12Series[i] - ema26Series[i];
  });

  const macdSeries = macdFullSeries.filter(v => v != null);

  if (macdSeries.length < 12) {
    return {
      json: {
        type: 'technical_signal',
        ticker,
        name,
        sektor,
        fehler: 'Zu wenige Datenpunkte für MACD',
        zeitstempel: new Date().toISOString()
      }
    };
  }

  const macdSignalSeriesRaw = emaSeries(macdSeries, 9);
  const macdSignalSeries = macdSignalSeriesRaw.filter(v => v != null);

  if (macdSignalSeries.length < 2) {
    return {
      json: {
        type: 'technical_signal',
        ticker,
        name,
        sektor,
        fehler: 'MACD-Signallinie konnte nicht berechnet werden',
        zeitstempel: new Date().toISOString()
      }
    };
  }

  const macdValRaw = macdSeries[macdSeries.length - 1];
  const macdPrevRaw = macdSeries[macdSeries.length - 2];

  const macdSignalValRaw = macdSignalSeries[macdSignalSeries.length - 1];
  const macdSignalPrevRaw = macdSignalSeries[macdSignalSeries.length - 2];

  const macdHistogrammRaw = macdValRaw - macdSignalValRaw;
  const macdHistogrammPrevRaw = macdPrevRaw - macdSignalPrevRaw;

  const macdVal = round(macdValRaw, 2);
  const macdSignalLinie = round(macdSignalValRaw, 2);
  const macdHistogramm = round(macdHistogrammRaw, 2);

  const macdKreuzungBullisch =
    macdPrevRaw <= macdSignalPrevRaw && macdValRaw > macdSignalValRaw;

  const macdKreuzungBaerisch =
    macdPrevRaw >= macdSignalPrevRaw && macdValRaw < macdSignalValRaw;

  const macdNullLinieBullisch =
    macdPrevRaw < 0 && macdValRaw > 0;

  const macdNullLinieBaerisch =
    macdPrevRaw > 0 && macdValRaw < 0;

  const macdHistogrammVerbessert =
    macdHistogrammRaw > macdHistogrammPrevRaw;

  const macdHistogrammVerschlechtert =
    macdHistogrammRaw < macdHistogrammPrevRaw;

  let macdSignal = 'Neutral';

  if (macdKreuzungBullisch) {
    macdSignal = 'Bullische Kreuzung';
  } else if (macdKreuzungBaerisch) {
    macdSignal = 'Bärische Kreuzung';
  } else if (macdValRaw > macdSignalValRaw) {
    macdSignal = 'Bullisch';
  } else if (macdValRaw < macdSignalValRaw) {
    macdSignal = 'Bärisch';
  }

  let macdKreuzung = 'keine';

  if (macdKreuzungBullisch) {
    macdKreuzung = 'Bullisch';
  } else if (macdKreuzungBaerisch) {
    macdKreuzung = 'Bärisch';
  }

  let macdNullLinie = 'keine';

  if (macdNullLinieBullisch) {
    macdNullLinie = 'Bullisch';
  } else if (macdNullLinieBaerisch) {
    macdNullLinie = 'Bärisch';
  }

  // ------------------------------------------------------------
  // Trend / EMA20
  // ------------------------------------------------------------

  const ema20Raw = ema(closes, 20);
  const ema20v = round(ema20Raw, 2);
  const trendAufwaerts = aktuellerKurs > ema20Raw;

  // ------------------------------------------------------------
  // Bollinger-Bänder
  // ------------------------------------------------------------

  const bb20 = closes.slice(-20);
  const bbAvg = bb20.reduce((a, b) => a + b, 0) / 20;
  const bbStd = Math.sqrt(
    bb20.map(p => Math.pow(p - bbAvg, 2)).reduce((a, b) => a + b, 0) / 20
  );

  const bbOben = bbAvg + 2 * bbStd;
  const bbUnten = bbAvg - 2 * bbStd;

  const kursBeiOben = aktuellerKurs >= bbOben * 0.995;
  const kursBeiUnten = aktuellerKurs <= bbUnten * 1.005;

  // ------------------------------------------------------------
  // 52-Wochen-Werte / Ersatz über vorhandene Daten
  // ------------------------------------------------------------

  const hoch52wRaw =
    meta.fiftyTwoWeekHigh?.raw ||
    meta.fiftyTwoWeekHigh ||
    (highs.length > 0 ? Math.max(...highs) : aktuellerKurs);

  const tief52wRaw =
    meta.fiftyTwoWeekLow?.raw ||
    meta.fiftyTwoWeekLow ||
    (lows.length > 0 ? Math.min(...lows) : aktuellerKurs);

  const hoch52w = round(hoch52wRaw, 2);
  const tief52w = round(tief52wRaw, 2);

  // ------------------------------------------------------------
  // Volumen
  // ------------------------------------------------------------

  const avgVol = vols.length > 0
    ? vols.reduce((a, b) => a + b, 0) / vols.length
    : 0;

  const lastVol = vols.length > 0
    ? vols[vols.length - 1]
    : 0;

  const volFaktorRaw =
    avgVol > 0 && lastVol > 0
      ? lastVol / avgVol
      : null;

  const volFaktor = volFaktorRaw !== null
    ? round(volFaktorRaw, 1)
    : null;

  const volumenErhoeht = volFaktor !== null && volFaktor > 1.5;
  const volumenOk = volFaktor !== null && volFaktor > 1.0;

  // ------------------------------------------------------------
  // Richtung bestimmen
  // ------------------------------------------------------------
  // "long" = mögliche Erholung / Aufwärtsbewegung
  // "short" = mögliche Schwäche / Rücklauf
  // "neutral" = keine klare Richtung

  let richtung = 'neutral';

  if (macdKreuzungBullisch && rsiVal < 60) {
    richtung = 'long';
  } else if (macdKreuzungBaerisch && rsiVal > 40) {
    richtung = 'short';
  } else if (rsiVal < 35 && kursBeiUnten) {
    richtung = 'long';
  } else if (rsiVal > 65 && kursBeiOben) {
    richtung = 'short';
  } else if (rsiVal < 35) {
    richtung = 'long';
  } else if (rsiVal > 65) {
    richtung = 'short';
  } else if (macdValRaw > macdSignalValRaw && macdHistogrammVerbessert) {
    richtung = 'long';
  } else if (macdValRaw < macdSignalValRaw && macdHistogrammVerschlechtert) {
    richtung = 'short';
  }

  // ------------------------------------------------------------
  // Technisches Punktesystem
  // ------------------------------------------------------------

  let punkte = 0;
  const signalGruende = [];

  // RSI
  if (rsiVal < 25 || rsiVal > 75) {
    punkte += 3;
    signalGruende.push('RSI extrem');
  } else if (rsiVal < 32 || rsiVal > 68) {
    punkte += 2;
    signalGruende.push('RSI stark');
  } else if (rsiVal < 38 || rsiVal > 62) {
    punkte += 1;
    signalGruende.push('RSI erhöht');
  }

  // MACD
  if (macdKreuzungBullisch) {
    punkte += 3;
    signalGruende.push('MACD bullische Kreuzung');
  } else if (macdKreuzungBaerisch) {
    punkte += 3;
    signalGruende.push('MACD bärische Kreuzung');
  } else if (macdNullLinieBullisch) {
    punkte += 2;
    signalGruende.push('MACD über Nulllinie');
  } else if (macdNullLinieBaerisch) {
    punkte += 2;
    signalGruende.push('MACD unter Nulllinie');
  } else if (macdHistogrammVerbessert && richtung === 'long') {
    punkte += 1;
    signalGruende.push('MACD verbessert sich');
  } else if (macdHistogrammVerschlechtert && richtung === 'short') {
    punkte += 1;
    signalGruende.push('MACD verschlechtert sich');
  } else {
    punkte += 1;
    signalGruende.push('MACD aktiv');
  }

  // Bollinger
  if (kursBeiOben || kursBeiUnten) {
    punkte += 2;
    signalGruende.push('Bollinger-Grenze');
  }

  // Trend-Bestätigung
  if (
    (richtung === 'long' && trendAufwaerts) ||
    (richtung === 'short' && !trendAufwaerts)
  ) {
    punkte += 1;
    signalGruende.push('Trend bestätigt');
  }

  // Volumen
  if (volumenErhoeht) {
    punkte += 2;
    signalGruende.push('Volumen erhöht');
  } else if (volumenOk) {
    punkte += 1;
    signalGruende.push('Volumen normal');
  }

  // Starke Tagesbewegung
  if (veraenderungPct > 2.5) {
    punkte += 1;
    signalGruende.push('Starke Bewegung');
  }

  // ------------------------------------------------------------
  // Technische Signalstärke
  // ------------------------------------------------------------

  let signalStaerke;

  if (punkte >= 6) {
    signalStaerke = 'hoch';
  } else if (punkte >= 3) {
    signalStaerke = 'mittel';
  } else {
    signalStaerke = 'niedrig';
  }

  // ------------------------------------------------------------
  // Phase 6 (fachliche Ueberarbeitung, Paket 18, 2026-07-31): getrennte
  // technische Strategiesignale statt eines gemischten Gesamtscores. Jedes
  // Signal wird ausschliesslich aus den oben bereits real berechneten Werten
  // abgeleitet (RSI/MACD/Bollinger/EMA20/52-Wochen/Volumen) - keine KI, keine
  // erfundene Evidenz. Das bestehende Punktesystem (punkte/signalGruende)
  // bleibt unveraendert als Gesamtwert erhalten (Rueckwaertskompatibilitaet).
  // ------------------------------------------------------------

  const dataQuality = Math.min(1, round(closes.length / 60, 2));
  const bbWidthPct = bbAvg > 0 ? (bbOben - bbUnten) / bbAvg : 0;

  // ------------------------------------------------------------
  // Welle 2, AP1+AP2 (2026-08-01): strategie-spezifische Stop/Ziel/Entry-Zone
  // je Strategiefamilie, aufbauend auf dem bereits berechneten ATR (Phase 7,
  // Welle 1). Getrennt von der bestehenden ATR_STOP_MULTIPLIER/ATR_TARGET_
  // MULTIPLIER (1.5/2.5), die weiterhin fuer den kombinierten Signalwert
  // (handelsBewertung.atrStop/atrTarget) gilt (Rueckwaertskompatibilitaet).
  // ------------------------------------------------------------
  const STRATEGY_RULE_VERSION = 'strategy-v1';
  const STRATEGY_ATR_MULTIPLIERS = {
    mean_reversion:  { stop: 1.0, target: 1.5 },
    trend_following: { stop: 1.5, target: 2.5 },
    breakout:        { stop: 1.0, target: 3.0 }
  };
  function strategyStopTargetEntry(strategyKey, direction, kurs, atr) {
    if (direction === 'neutral' || atr === null || atr === undefined || !(kurs > 0)) {
      return { stop: null, target: null, entryLow: null, entryHigh: null };
    }
    const m = STRATEGY_ATR_MULTIPLIERS[strategyKey];
    const stop = direction === 'long' ? kurs - m.stop * atr : kurs + m.stop * atr;
    const target = direction === 'long' ? kurs + m.target * atr : kurs - m.target * atr;
    const entryBuffer = kurs * 0.003;
    const entryLow = direction === 'long' ? kurs - entryBuffer : kurs;
    const entryHigh = direction === 'long' ? kurs : kurs + entryBuffer;
    return { stop: round(stop, 2), target: round(target, 2), entryLow: round(entryLow, 2), entryHigh: round(entryHigh, 2) };
  }
  function timeStopFor(days) {
    return new Date(Date.now() + days * 86400000).toISOString();
  }

  // --- Mean-Reversion: RSI-Extremwert + Bollinger-Band-Beruehrung + Abstand EMA20 ---
  const meanReversionEvidence = [];
  let mrScore = 0;
  let mrDirection = 'neutral';
  if (rsiVal < 25 || rsiVal > 75) { mrScore += 0.4; meanReversionEvidence.push('RSI extrem (' + rsiVal.toFixed(1) + ')'); }
  else if (rsiVal < 32 || rsiVal > 68) { mrScore += 0.25; meanReversionEvidence.push('RSI stark (' + rsiVal.toFixed(1) + ')'); }
  else if (rsiVal < 38 || rsiVal > 62) { mrScore += 0.15; meanReversionEvidence.push('RSI erhoeht (' + rsiVal.toFixed(1) + ')'); }
  if (kursBeiOben) { mrScore += 0.35; meanReversionEvidence.push('Kurs am oberen Bollinger-Band'); }
  if (kursBeiUnten) { mrScore += 0.35; meanReversionEvidence.push('Kurs am unteren Bollinger-Band'); }
  const emaDistPct = ema20Raw > 0 ? Math.abs(aktuellerKurs - ema20Raw) / ema20Raw : 0;
  if (emaDistPct > 0.01) { const c = Math.min(0.25, emaDistPct * 5); mrScore += c; meanReversionEvidence.push('Abstand zu EMA20: ' + (emaDistPct * 100).toFixed(1) + '%'); }
  if (rsiVal < 35 || kursBeiUnten) mrDirection = 'long';
  else if (rsiVal > 65 || kursBeiOben) mrDirection = 'short';
  const mrStopTargetEntry = strategyStopTargetEntry('mean_reversion', mrDirection, aktuellerKurs, atr14);
  const meanReversionSignal = {
    strategy: 'mean_reversion',
    direction: mrDirection,
    raw_score: round(Math.min(1, mrScore), 2),
    regime_fit: round(Math.min(1, Math.max(0, 1 - bbWidthPct * 5)), 2),
    data_quality: dataQuality,
    expected_horizon_days: 3,
    evidence: meanReversionEvidence,
    entry_zone_low: mrStopTargetEntry.entryLow,
    entry_zone_high: mrStopTargetEntry.entryHigh,
    stop_price: mrStopTargetEntry.stop,
    target_price: mrStopTargetEntry.target,
    time_stop_at: mrDirection !== 'neutral' ? timeStopFor(3) : null,
    rule_version: STRATEGY_RULE_VERSION
  };

  // --- Trend-Following: MACD-Kreuzung/Nulllinie/Histogramm + EMA20-Trendbestaetigung ---
  const trendFollowingEvidence = [];
  let tfScore = 0;
  let tfDirection = 'neutral';
  if (macdKreuzungBullisch) { tfScore += 0.4; trendFollowingEvidence.push('MACD bullische Kreuzung'); }
  else if (macdKreuzungBaerisch) { tfScore += 0.4; trendFollowingEvidence.push('MACD baerische Kreuzung'); }
  else if (macdNullLinieBullisch) { tfScore += 0.3; trendFollowingEvidence.push('MACD ueber Nulllinie gekreuzt'); }
  else if (macdNullLinieBaerisch) { tfScore += 0.3; trendFollowingEvidence.push('MACD unter Nulllinie gekreuzt'); }
  else if (macdHistogrammVerbessert) { tfScore += 0.15; trendFollowingEvidence.push('MACD-Histogramm verbessert sich'); }
  else if (macdHistogrammVerschlechtert) { tfScore += 0.15; trendFollowingEvidence.push('MACD-Histogramm verschlechtert sich'); }
  if (trendAufwaerts) { trendFollowingEvidence.push('Kurs ueber EMA20 (Aufwaertstrend)'); } else { trendFollowingEvidence.push('Kurs unter EMA20 (Abwaertstrend)'); }
  const macdMomentumPct = aktuellerKurs > 0 ? Math.abs(macdHistogrammRaw) / aktuellerKurs : 0;
  tfScore += Math.min(0.3, macdMomentumPct * 20);
  if (macdValRaw > macdSignalValRaw && trendAufwaerts) tfDirection = 'long';
  else if (macdValRaw < macdSignalValRaw && !trendAufwaerts) tfDirection = 'short';
  const tfStopTargetEntry = strategyStopTargetEntry('trend_following', tfDirection, aktuellerKurs, atr14);
  const trendFollowingSignal = {
    strategy: 'trend_following',
    direction: tfDirection,
    raw_score: round(Math.min(1, tfScore), 2),
    regime_fit: round(Math.min(1, bbWidthPct * 5), 2),
    data_quality: dataQuality,
    expected_horizon_days: 15,
    evidence: trendFollowingEvidence,
    entry_zone_low: tfStopTargetEntry.entryLow,
    entry_zone_high: tfStopTargetEntry.entryHigh,
    stop_price: tfStopTargetEntry.stop,
    target_price: tfStopTargetEntry.target,
    time_stop_at: tfDirection !== 'neutral' ? timeStopFor(15) : null,
    rule_version: STRATEGY_RULE_VERSION
  };

  // --- Breakout: Naehe zum 52-Wochen-Hoch/-Tief + Volumenfaktor + Tagesbewegung ---
  const breakoutEvidence = [];
  let boScore = 0;
  let boDirection = 'neutral';
  const distZuHoch = hoch52wRaw > 0 ? (hoch52wRaw - aktuellerKurs) / hoch52wRaw : 1;
  const distZuTief = tief52wRaw > 0 ? (aktuellerKurs - tief52wRaw) / tief52wRaw : 1;
  if (distZuHoch < 0.02) { boScore += 0.4; boDirection = 'long'; breakoutEvidence.push('Kurs innerhalb 2% des 52-Wochen-Hochs'); }
  if (distZuTief < 0.02) { boScore += 0.4; boDirection = 'short'; breakoutEvidence.push('Kurs innerhalb 2% des 52-Wochen-Tiefs'); }
  if (volumenErhoeht) { boScore += 0.35; breakoutEvidence.push('Volumen deutlich erhoeht (' + volFaktor + 'x Durchschnitt)'); }
  else if (volumenOk) { boScore += 0.15; breakoutEvidence.push('Volumen ueber Durchschnitt (' + volFaktor + 'x)'); }
  if (Math.abs(veraenderungPctRaw) > 2.5) { boScore += 0.25; breakoutEvidence.push('Starke Tagesbewegung (' + veraenderungPctRaw.toFixed(1) + '%)'); }
  const boStopTargetEntry = strategyStopTargetEntry('breakout', boDirection, aktuellerKurs, atr14);
  const breakoutSignal = {
    strategy: 'breakout',
    direction: boDirection,
    raw_score: round(Math.min(1, boScore), 2),
    regime_fit: volFaktorRaw !== null ? round(Math.min(1, volFaktorRaw / 2), 2) : 0.5,
    data_quality: dataQuality,
    expected_horizon_days: 7,
    evidence: breakoutEvidence,
    entry_zone_low: boStopTargetEntry.entryLow,
    entry_zone_high: boStopTargetEntry.entryHigh,
    stop_price: boStopTargetEntry.stop,
    target_price: boStopTargetEntry.target,
    time_stop_at: boDirection !== 'neutral' ? timeStopFor(7) : null,
    rule_version: STRATEGY_RULE_VERSION,
    // AP2 Breakout-Sonderregel: kein Signal aus einer nur 3-monatigen Ersatzhistorie
    // (siehe Welle 1 breakoutHistoryAusreichend) - wird hier zusaetzlich als
    // Blocker im normalisierten Signal sichtbar gemacht (fuer strategy_signals).
    blockers: breakoutHistoryAusreichend ? [] : [{ code: 'HISTORY_252_MISSING', severity: 'hard', source: 'technical_signal', message: 'Breakout ohne ausreichende 252-Tage-Historie/Meta-52-Wochen-Wert', observed_value: closes.length, required_value: '>= 252 oder Meta-52w' }]
  };

  // Fuehrende Strategie: hoechster raw_score gewinnt.
  const strategySignals = [meanReversionSignal, trendFollowingSignal, breakoutSignal];
  const dominantStrategy = strategySignals.reduce((a, b) => (b.raw_score > a.raw_score ? b : a)).strategy;

  // Bekannte Korrelationen zwischen den zugrundeliegenden Indikatoren (statisch dokumentiert,
  // nicht live berechnet - dafuer fehlt eine historische Zeitreihe je Indikatorpaar):
  // MACD-Kreuzung und MACD-Histogramm-Richtung stammen aus derselben zugrundeliegenden
  // EMA12/EMA26-Differenz, sind also nicht unabhaengig voneinander. RSI und Bollinger-Band-
  // Beruehrung sind beide Auspraegungen "Kurs weit vom juengsten Durchschnitt entfernt" und
  // korrelieren dadurch typischerweise stark miteinander.
  const KNOWN_INDICATOR_CORRELATIONS = [
    'macd_kreuzung und macd_histogramm_trend (beide aus derselben EMA12/EMA26-Differenz)',
    'rsi und bollinger_beruehrung (beide messen Abweichung vom gleitenden Durchschnitt)'
  ];

  // ------------------------------------------------------------
  // Praktische Handelsbewertung
  // ------------------------------------------------------------
  // Diese Bewertung berücksichtigt deine Realität:
  // - du handelst selten
  // - Gebühren/Spread sind relevant
  // - kleine Bewegungen reichen nicht
  // - ohne Bestätigung nur beobachten

  const gebuehrenPufferPct = 2.0;
  const minBruttoPotenzialPct = 3.0;
  const gutesPotenzialPct = 4.5;
  const minCrv = 1.8;

  const macdBestaetigtLong =
    richtung === 'long' &&
    (
      macdKreuzung === 'Bullisch' ||
      (macdValRaw > macdSignalValRaw && macdHistogrammVerbessert)
    );

  const macdBestaetigtShort =
    richtung === 'short' &&
    (
      macdKreuzung === 'Bärisch' ||
      (macdValRaw < macdSignalValRaw && macdHistogrammVerschlechtert)
    );

  const macdBestaetigtRichtung =
    macdBestaetigtLong || macdBestaetigtShort;

  let zielKurs = null;
  let stopKurs = null;
  let zielLogik = '';
  let stopLogik = '';

  if (richtung === 'long') {
    // Für Long: Ziel ist eine realistische Erholung Richtung EMA20/Bollinger-Mitte.
    const zielKandidaten = [ema20Raw, bbAvg].filter(v => v && v > aktuellerKurs);
    zielKurs = zielKandidaten.length > 0 ? Math.min(...zielKandidaten) : null;

    // Falls beide unterhalb liegen, kein sinnvolles Long-Ziel.
    stopKurs = lows.length > 0 ? Math.min(lows[lows.length - 1], bbUnten) : bbUnten;

    zielLogik = 'Erholung Richtung EMA20/Bollinger-Mitte';
    stopLogik = 'unter aktuellem Tief bzw. unterem Bollinger-Bereich';
  }

  if (richtung === 'short') {
    // Für Short: Ziel ist ein Rücklauf Richtung EMA20/Bollinger-Mitte.
    const zielKandidaten = [ema20Raw, bbAvg].filter(v => v && v < aktuellerKurs);
    zielKurs = zielKandidaten.length > 0 ? Math.max(...zielKandidaten) : null;

    // Falls beide oberhalb liegen, kein sinnvolles Short-Ziel.
    stopKurs = highs.length > 0 ? Math.max(highs[highs.length - 1], bbOben) : bbOben;

    zielLogik = 'Rücklauf Richtung EMA20/Bollinger-Mitte';
    stopLogik = 'über aktuellem Hoch bzw. oberem Bollinger-Bereich';
  }
  // Phase 7 (Paket 16): ATR-basierte Stop/Ziel-Alternative neben der
  // bestehenden EMA20/Bollinger-Logik oben ("legacy"). Formel wie im Auftrag:
  // Stop = Einstieg -/+ 1.5x ATR, Ziel = Einstieg +/- 2.5x ATR (long/short).
  let atrStop = null;
  let atrTarget = null;
  if (atr14 !== null) {
    if (richtung === 'long') {
      atrStop = aktuellerKurs - ATR_STOP_MULTIPLIER * atr14;
      atrTarget = aktuellerKurs + ATR_TARGET_MULTIPLIER * atr14;
    } else if (richtung === 'short') {
      atrStop = aktuellerKurs + ATR_STOP_MULTIPLIER * atr14;
      atrTarget = aktuellerKurs - ATR_TARGET_MULTIPLIER * atr14;
    }
  }


  const bruttoPotenzialPct =
    richtung === 'long'
      ? pctMove(aktuellerKurs, zielKurs)
      : richtung === 'short'
        ? pctMove(zielKurs, aktuellerKurs)
        : null;

  const risikoPct =
    richtung === 'long'
      ? absPctMove(aktuellerKurs, stopKurs)
      : richtung === 'short'
        ? absPctMove(aktuellerKurs, stopKurs)
        : null;

  const nettoPotenzialPct =
    bruttoPotenzialPct !== null
      ? bruttoPotenzialPct - gebuehrenPufferPct
      : null;

  const crv =
    bruttoPotenzialPct !== null && risikoPct !== null && risikoPct > 0
      ? bruttoPotenzialPct / risikoPct
      : null;

  const potenzialAusreichend =
    bruttoPotenzialPct !== null && bruttoPotenzialPct >= minBruttoPotenzialPct;

  const potenzialGut =
    bruttoPotenzialPct !== null && bruttoPotenzialPct >= gutesPotenzialPct;

  const crvOk =
    crv !== null && crv >= minCrv;

  const signalHoch = signalStaerke === 'hoch';
  const signalMindestensMittel = signalStaerke === 'hoch' || signalStaerke === 'mittel';

  let handelsStatus = 'nur_info';
  let handelsStatusText = '⚪ Nur Info';
  let entscheidungKurz = '';
  let entscheidungLang = '';

  if (richtung === 'neutral') {
    handelsStatus = 'nur_info';
    handelsStatusText = '⚪ Nur Info';
    entscheidungKurz = 'Keine klare Richtung.';
    entscheidungLang =
      'Die Aktie ist technisch auffällig, aber die Richtung ist nicht klar genug. Für deine Handelsweise ist das kein sinnvoller Kandidat.';
  } else if (!potenzialAusreichend) {
    handelsStatus = 'ignorieren';
    handelsStatusText = '🔴 Ignorieren';
    entscheidungKurz = 'Zu wenig Spielraum.';
    entscheidungLang =
      'Das technische Signal ist vorhanden, aber der mögliche Spielraum ist zu klein. Nach Gebühren und Spread bleibt voraussichtlich zu wenig übrig.';
  } else if (!macdBestaetigtRichtung) {
    handelsStatus = 'beobachten';
    handelsStatusText = '🟡 Beobachten';
    entscheidungKurz = 'Interessant, aber noch nicht bestätigt.';
    entscheidungLang =
      richtung === 'long'
        ? 'Die Aktie könnte sich erholen, aber der MACD bestätigt die Long-Richtung noch nicht. Besser erst auf Stabilisierung oder klarere Momentum-Drehung warten.'
        : 'Die Aktie wirkt überhitzt, aber der MACD bestätigt die Short-Richtung noch nicht. Besser erst auf ein klares Schwächesignal warten.';
  } else if (signalHoch && potenzialGut && crvOk) {
    handelsStatus = 'handelskandidat';
    handelsStatusText = '🟢 Handelskandidat';
    entscheidungKurz = 'Technik, Bestätigung und Spielraum passen zusammen.';
    entscheidungLang =
      'Das Setup ist technisch bestätigt und hat genügend rechnerischen Spielraum über dem Gebührenpuffer. Trotzdem bleibt es ein Beobachtungssignal und keine Anlageberatung.';
  } else if (signalMindestensMittel && macdBestaetigtRichtung && potenzialAusreichend) {
    handelsStatus = 'beobachten';
    handelsStatusText = '🟡 Beobachten';
    entscheidungKurz = 'Bestätigt, aber noch nicht stark genug.';
    entscheidungLang =
      'Die Richtung ist technisch plausibel, aber Qualität oder Spielraum reichen noch nicht für einen klaren Handelskandidaten.';
  } else {
    handelsStatus = 'nur_info';
    handelsStatusText = '⚪ Nur Info';
    entscheidungKurz = 'Auffällig, aber nicht stark genug.';
    entscheidungLang =
      'Das Signal reicht für eine Notiz, aber nicht für eine ernsthafte Handelsbeobachtung.';
  }

  const handelsBewertung = {
    status: handelsStatus,
    statusText: handelsStatusText,
    entscheidungKurz,
    entscheidungLang,

    gebuehrenPufferPct,
    minBruttoPotenzialPct,
    zielKurs: zielKurs !== null ? round(zielKurs, 2) : null,
    stopKurs: stopKurs !== null ? round(stopKurs, 2) : null,
    zielLogik,
    stopLogik,

    bruttoPotenzialPct: bruttoPotenzialPct !== null ? round(bruttoPotenzialPct, 2) : null,
    nettoPotenzialPct: nettoPotenzialPct !== null ? round(nettoPotenzialPct, 2) : null,
    risikoPct: risikoPct !== null ? round(risikoPct, 2) : null,
    crv: crv !== null ? round(crv, 2) : null,

    potenzialAusreichend,
    potenzialGut,
    crvOk,
    macdBestaetigtRichtung,

    // Phase 7 (Paket 16): ATR/Volatilitaet + legacy- vs. ATR-basierte Stop/Ziel-Werte
    atr14: atr14 !== null ? round(atr14, 4) : null,
    realizedVol20d: realizedVol20 !== null ? round(realizedVol20, 4) : null,
    realizedVol60d: realizedVol60 !== null ? round(realizedVol60, 4) : null,
    avgDailyRange14: avgDailyRange14 !== null ? round(avgDailyRange14, 4) : null,
    legacyStop: stopKurs !== null ? round(stopKurs, 2) : null,
    legacyTarget: zielKurs !== null ? round(zielKurs, 2) : null,
    atrStop: atrStop !== null ? round(atrStop, 2) : null,
    atrTarget: atrTarget !== null ? round(atrTarget, 2) : null
  };

  // ------------------------------------------------------------
  // Ergebnisobjekt
  // ------------------------------------------------------------

  const signal = {
    type: 'technical_signal',
    ticker,
    name,
    sektor,

    aktuellerKurs: round(aktuellerKurs, 2),
    veraenderung,

    rsi: rsiVal,
    rsiSignal,

    macd: macdVal,
    macdSignalLinie,
    macdHistogramm,
    macdSignal,
    macdKreuzung,
    macdNullLinie,
    macdHistogrammTrend: macdHistogrammVerbessert
      ? 'verbessert'
      : macdHistogrammVerschlechtert
        ? 'verschlechtert'
        : 'neutral',

    trend: trendAufwaerts ? 'Aufwärts' : 'Abwärts',
    ema20: ema20v,

    bb_oben: round(bbOben, 2),
    bb_mitte: round(bbAvg, 2),
    bb_unten: round(bbUnten, 2),
    kursBeiBollinger: kursBeiOben ? 'oben' : kursBeiUnten ? 'unten' : 'mitte',

    hoch52w,
    tief52w,
    abstandVomTief: tief52wRaw
      ? (((aktuellerKurs - tief52wRaw) / tief52wRaw) * 100).toFixed(1) + '%'
      : 'n/a',

    volumenFaktor: volFaktor !== null ? volFaktor + 'x' : 'n/a',

    signalPunkte: punkte,
    signalGruende: signalGruende.join(', '),
    signalStaerke,
    richtung,

    handelsBewertung,

    // Phase 6 (Paket 18): getrennte Strategiesignale
    meanReversionSignal,
    trendFollowingSignal,
    breakoutSignal,
    dominantStrategy,
    knownIndicatorCorrelations: KNOWN_INDICATOR_CORRELATIONS,

    // Welle 1, AP2+AP3+AP4: Datenqualitaet/Mindesthistorie/Sitzungsstatus
    dataQualityStatus,
    dataQualityScore,
    dataQualityIssues: qualityIssues,
    historyLengthDays: closes.length,
    breakoutHistoryAusreichend,
    volatilityHistoryAusreichend,
    kurzfristHistoryAusreichend,
    sessionStatus,

    // Welle 1, AP1: letzte gueltige Kerze fuer die vollstaendige OHLCV-Persistenz
    // in trading.stock_price_history (siehe "Kurshistorie: SQL bauen").
    letzteKerzeOpen: letzteGueltigeKerze ? letzteGueltigeKerze.open : null,
    letzteKerzeHigh: letzteGueltigeKerze ? letzteGueltigeKerze.high : null,
    letzteKerzeLow: letzteGueltigeKerze ? letzteGueltigeKerze.low : null,
    letzteKerzeClose: letzteGueltigeKerze ? letzteGueltigeKerze.close : null,
    letzteKerzeVolume: letzteGueltigeKerze ? letzteGueltigeKerze.volume : null,
    letzteKerzeAdjClose: letzteGueltigeKerze ? letzteGueltigeKerze.adjClose : null,
    letzteKerzeTimestamp: letzteGueltigeKerze ? letzteGueltigeKerze.ts : null,
    waehrung: meta.currency || null,

    hinweis: 'Technisches Beobachtungssignal, keine Anlageberatung.',
    zeitstempel: new Date().toISOString()
  };

  // ------------------------------------------------------------
  // In Static Data speichern
  // ------------------------------------------------------------

  const sd = $getWorkflowStaticData('global');

  if (!sd.technischeSignale) {
    sd.technischeSignale = {};
  }

  sd.technischeSignale[ticker] = signal;

  return {
    json: signal
  };

} catch (e) {
  return {
    json: {
      type: 'technical_signal',
      ticker,
      name,
      fehler: e.message,
      zeitstempel: new Date().toISOString()
    }
  };
}

// TECHNISCHES SIGNAL FLACH AUFBEREITEN – snake_case
// Modus: runOnceForEachItem
// Gibt alle Felder in snake_case aus, passend zur stock_technical_signals DataTable.
// Static Data wird weiterhin als Fallback befüllt.

const s = $input.item.json;
const hb = s.handelsBewertung || {};

const str  = (v) => (v == null ? '' : String(v));
const num  = (v) => {
  const n = Number(v);
  return (v == null || v === '' || isNaN(n)) ? null : n;
};
const bool = (v) => (v === true || v === 'true' ? 'true' : 'false');

const flat = {
  // Basis
  ticker:                    str(s.ticker),
  name:                      str(s.name),
  sektor:                    str(s.sektor || ''),
  datum:                     new Date().toISOString().substring(0, 10),
  zeitstempel:               str(s.zeitstempel),
  type:                      str(s.type || 'technical_signal'),

  // Kurs
  aktueller_kurs:            num(s.aktuellerKurs),
  veraenderung:              str(s.veraenderung),

  // RSI
  rsi:                       num(s.rsi),
  rsi_signal:                str(s.rsiSignal),

  // MACD
  macd:                      num(s.macd),
  macd_signal_linie:         num(s.macdSignalLinie),
  macd_histogramm:           num(s.macdHistogramm),
  macd_signal:               str(s.macdSignal),
  macd_kreuzung:             str(s.macdKreuzung),
  macd_null_linie:           str(s.macdNullLinie),
  macd_histogramm_trend:     str(s.macdHistogrammTrend),

  // Trend
  trend:                     str(s.trend),
  ema20:                     num(s.ema20),
  richtung:                  str(s.richtung),

  // Bollinger
  bb_oben:                   num(s.bb_oben),
  bb_mitte:                  num(s.bb_mitte),
  bb_unten:                  num(s.bb_unten),
  kurs_bei_bollinger:        str(s.kursBeiBollinger),

  // 52-Wochen
  hoch_52w:                  num(s.hoch52w),
  tief_52w:                  num(s.tief52w),
  abstand_vom_tief:          str(s.abstandVomTief),

  // Volumen
  volumen_faktor:            str(s.volumenFaktor),

  // Signal-Bewertung
  signal_punkte:             num(s.signalPunkte),
  signal_gruende:            str(s.signalGruende),
  signal_staerke:            str(s.signalStaerke),

  // handelsBewertung flach (snake_case)
  handels_status:            str(hb.status),
  handels_status_text:       str(hb.statusText),
  entscheidung_kurz:         str(hb.entscheidungKurz),
  entscheidung_lang:         str(hb.entscheidungLang),
  ziel_kurs:                 num(hb.zielKurs),
  stop_kurs:                 num(hb.stopKurs),
  ziel_logik:                str(hb.zielLogik),
  stop_logik:                str(hb.stopLogik),
  gebuehren_puffer_pct:      num(hb.gebuehrenPufferPct),
  min_brutto_potenzial_pct:  num(hb.minBruttoPotenzialPct),
  brutto_potenzial_pct:      num(hb.bruttoPotenzialPct),
  netto_potenzial_pct:       num(hb.nettoPotenzialPct),
  risiko_pct:                num(hb.risikoPct),
  crv:                       num(hb.crv),
  potenzial_ausreichend:     bool(hb.potenzialAusreichend),
  potenzial_gut:             bool(hb.potenzialGut),
  crv_ok:                    bool(hb.crvOk),
  macd_bestaetigt_richtung:  bool(hb.macdBestaetigtRichtung),

  // Phase 7 (Paket 16): ATR/Volatilitaet + legacy- vs. ATR-Stop/Ziel
  atr_14:                    num(hb.atr14),
  realized_vol_20d:          num(hb.realizedVol20d),
  realized_vol_60d:          num(hb.realizedVol60d),
  avg_daily_range_14:        num(hb.avgDailyRange14),
  legacy_stop:               num(hb.legacyStop),
  legacy_target:             num(hb.legacyTarget),
  atr_stop:                  num(hb.atrStop),
  atr_target:                num(hb.atrTarget),

  // Phase 6 (Paket 18): getrennte Strategiesignale (als JSON-Text, Zielspalten sind jsonb)
  mean_reversion_signal_json:  s.meanReversionSignal ? JSON.stringify(s.meanReversionSignal) : null,
  trend_following_signal_json: s.trendFollowingSignal ? JSON.stringify(s.trendFollowingSignal) : null,
  breakout_signal_json:        s.breakoutSignal ? JSON.stringify(s.breakoutSignal) : null,
  dominant_strategy:           str(s.dominantStrategy),

  // Welle 1, AP2+AP3+AP4: Datenqualitaet/Mindesthistorie/Sitzungsstatus
  data_quality_status:          str(s.dataQualityStatus),
  data_quality_score:           num(s.dataQualityScore),
  data_quality_issues_json:     s.dataQualityIssues ? JSON.stringify(s.dataQualityIssues) : null,
  history_length_days:          num(s.historyLengthDays),
  breakout_history_ausreichend: bool(s.breakoutHistoryAusreichend),
  volatility_history_ausreichend: bool(s.volatilityHistoryAusreichend),
  kurzfrist_history_ausreichend:  bool(s.kurzfristHistoryAusreichend),
  session_status:                str(s.sessionStatus),

  // Welle 1, AP1: letzte Kerze (OHLCV) fuer die vollstaendige Persistenz in
  // trading.stock_price_history (siehe "Kurshistorie: SQL bauen").
  kerze_open:            num(s.letzteKerzeOpen),
  kerze_high:             num(s.letzteKerzeHigh),
  kerze_low:              num(s.letzteKerzeLow),
  kerze_close:            num(s.letzteKerzeClose),
  kerze_volume:           num(s.letzteKerzeVolume),
  kerze_adjusted_close:   num(s.letzteKerzeAdjClose),
  kerze_timestamp:        num(s.letzteKerzeTimestamp),
  waehrung:               str(s.waehrung || ''),

  // Sonstige
  hinweis:                   str(s.hinweis || 'Technisches Beobachtungssignal, keine Anlageberatung.'),
  status:                    str(s.fehler ? 'fehler' : 'ok'),
  fehler:                    str(s.fehler || '')
};

// Static Data Fallback weiterhin befüllen (für Kompatibilität)
const sd = $getWorkflowStaticData('global');
if (!sd.technischeSignale) sd.technischeSignale = {};
sd.technischeSignale[flat.ticker] = { ...flat, zeitstempel: flat.zeitstempel };

return { json: flat };

// SIGNAL + MARKTKONTEXT ZUSAMMENFÜHREN – Run Once for All Items
// Input: Marktumfeld-Zeilen aus "DB: Marktumfeld für Signal laden"
// Signale: aus "Signal: flach aufbereiten" (alle 15 frischen Signale)
//
// Gibt immer 15 technische Signale aus (type = technical_signal)
// Marktumfeld-Daten werden nur als Kontext ergänzt, nicht als eigene Items

const marktItems = $input.all().map(i => i.json || {});
const signalItems = $('Signal: flach aufbereiten').all();

// Nur echte Marktumfeld-Zeilen (mit symbol oder markt_status)
const marktRows = marktItems.filter(row =>
  row && (row.symbol || row.markt_status) &&
  row.type !== 'technical_signal'
);

// DAX als primären Referenzindex suchen
function findeReferenzIndex(signalTicker) {
  // Erster Versuch: DAX
  let kandidat = marktRows.find(m =>
    String(m.symbol || '') === '^GDAXI' ||
    String(m.name || '').toLowerCase() === 'dax'
  );
  // Fallback: erster verfügbarer Markt
  if (!kandidat && marktRows.length > 0) {
    kandidat = marktRows[0];
  }
  return kandidat || null;
}

return signalItems.map(item => {
  const signal = item.json || {};
  const markt = findeReferenzIndex(signal.ticker);

  if (!markt) {
    return {
      json: {
        ...signal,
        // Sicherstellen: type bleibt technical_signal
        ticker: signal.ticker,
        name: signal.name,
        type: signal.type || 'technical_signal',
        // Fallback-Marktfelder
        referenz_index: '',
        referenz_index_name: '',
        index_veraenderung_pct: '',
        index_trend: '',
        index_markt_status: 'unbekannt',
        relative_staerke_pct: '',
        markt_bestaetigt_signal: 'false',
        markt_hinweis: 'Kein Marktumfeld verfügbar – Signal ohne Marktfilter gespeichert.',
        extra_kontext_hinweis: 'Marktumfeld-Daten fehlten beim Speichern.'
      }
    };
  }

  // Relative Stärke berechnen
  const aktieVPct = parseFloat(String(signal.veraenderung || '').replace('%','')) || null;
  const indexVPct = parseFloat(String(markt.veraenderung_pct || '')) || null;
  const relStaerke = (aktieVPct !== null && indexVPct !== null)
    ? parseFloat((aktieVPct - indexVPct).toFixed(2))
    : null;

  const marktStatus = markt.markt_status || '';
  const richtung = signal.richtung || '';
  const hs = signal.handels_status || '';

  let markt_bestaetigt = 'false';
  let markt_hinweis = 'Marktumfeld neutral oder uneinheitlich.';

  if (marktStatus === 'risk_on' && (hs === 'handelskandidat' || hs === 'beobachten') && richtung === 'long') {
    if (relStaerke !== null && relStaerke > 0) {
      markt_bestaetigt = 'true';
      markt_hinweis = 'Aktie stärker als Referenzmarkt; Marktumfeld bestätigt Long-Signal.';
    }
  } else if (marktStatus === 'risk_off' && richtung === 'short') {
    if (relStaerke !== null && relStaerke < 0) {
      markt_bestaetigt = 'true';
      markt_hinweis = 'Aktie schwächer als Referenzmarkt; Marktumfeld bestätigt Short-Signal.';
    } else {
      markt_hinweis = 'Markt risk_off; Long-Signal vorsichtiger bewerten.';
    }
  }

  return {
    json: {
      ...signal,
      // Immer überschreiben: Signal bleibt Signal
      ticker: signal.ticker,
      name: signal.name,
      type: signal.type || 'technical_signal',
      // Marktkontext ergänzen
      referenz_index: markt.symbol || '',
      referenz_index_name: markt.name || '',
      index_veraenderung_pct: indexVPct !== null ? indexVPct : '',
      index_trend: markt.trend || '',
      index_markt_status: marktStatus,
      relative_staerke_pct: relStaerke !== null ? relStaerke : '',
      markt_bestaetigt_signal: markt_bestaetigt,
      markt_hinweis: markt_hinweis,
      extra_kontext_hinweis: `Marktumfeld ergänzt aus ${markt.name || markt.symbol || 'unbekannt'}.`
    }
  };
});

// SIGNAL: MARKTUMFELD ERGÄNZEN – Run Once for All Items (Pass-through)
// Alle 15 Signale werden unverändert weitergegeben.
// Die Marktumfeld-Anreicherung wurde bereits in "Signal + Marktkontext zusammenführen" vorgenommen.
return $input.all().map(item => ({ json: item.json }));

// SIGNAL: ROUTING – Run Once for All Items
// Input: DB-Zeilen aus "DB: Signal suchen" (alle vorhandenen Signale aus stock_technical_signals)
// Signalquelle: frische 15 Signale aus "Signal: Marktumfeld ergänzen"
//
// Logik:
// - Über frische Signale iterieren (NICHT über DB-Zeilen)
// - DB-Zeilen nach ticker indexieren
// - _rowExists = true → Update; _rowExists = false → Insert
// - Bei leerer DB: alle 15 Signale als neu (Insert)

const dbRows = $input.all().map(i => i.json || {});
const signalItems = $('Signal: Marktumfeld ergänzen').all().map(i => i.json || {});

// DB-Zeilen nach ticker indexieren (nur echte Zeilen mit id)
const foundByTicker = {};
for (const row of dbRows) {
  const ticker = String(row.ticker || '').trim();
  const hasId =
    row.id !== undefined &&
    row.id !== null &&
    String(row.id).trim() !== '';
  if (ticker && hasId) {
    foundByTicker[ticker] = row;
  }
}

// Über frische Signale laufen – Ticker-Bestand bleibt erhalten
return signalItems.map(signal => {
  const ticker = String(signal.ticker || '').trim();
  const found = foundByTicker[ticker];

  const rowExists =
    found !== undefined &&
    found.id !== undefined &&
    found.id !== null &&
    String(found.id).trim() !== '';

  return {
    json: {
      ...signal,
      _existing_id: rowExists ? String(found.id) : '',
      _rowExists: Boolean(rowExists)
    }
  };
});

